var cachedPath='';
try{ cachedPath=String(source.get(cacheKey)||''); }catch(e0){}
if(cachedPath){
  try{
    var cb=java.readFile(cachedPath);
    if(cb&&cb.length>100000){ cb=null; try{Packages.java.lang.System.gc();}catch(e01){} java.toast('使用本地缓存，秒播'); return 'file://'+FVCD+cachedPath; }
    cb=null;
  }catch(e02){}
}
java.toast('正在解密视频（'+defName+'）…');
var keyHex=RG_cencKey(java,d.spadeA);
var hexStr=String(java.ajax(d.url+',{'+String.fromCharCode(34)+'type'+String.fromCharCode(34)+':'+String.fromCharCode(34)+'hex'+String.fromCharCode(34)+','+String.fromCharCode(34)+'retry'+String.fromCharCode(34)+':2,'+String.fromCharCode(34)+'headers'+String.fromCharCode(34)+':{'+String.fromCharCode(34)+'User-Agent'+String.fromCharCode(34)+':'+String.fromCharCode(34)+'com.phoenix.read/72932'+String.fromCharCode(34)+'}}'));
