if(r.bv2c)throw new Error('该清晰度使用了字节私有编码，安卓解码器不支持');
var outHex=RG_encodeHex(bytes);
bytes=null;
try{ Packages.java.lang.System.gc(); }catch(g1){}
var path=String(java.downloadFile(outHex,'https://x/'+cacheKey+'.mp4,{'+String.fromCharCode(34)+'type'+String.fromCharCode(34)+':'+String.fromCharCode(34)+'mp4'+String.fromCharCode(34)+'}'));
outHex=null;
try{ Packages.java.lang.System.gc(); }catch(g2){}
try{
  source.put(cacheKey,path);
  var kl=String(source.get('fv_keys')||'');
  var ka=kl?kl.split(','):[];
  if(ka.indexOf(cacheKey)<0)ka.push(cacheKey);
  source.put('fv_keys',ka.join(','));
}catch(e9){}
FV_trimCache(java,source);
return 'file://'+FVCD+path;
}catch(e){ return 'DIAG_ERR: '+String(e.message||e); }
